// A full-screen selection of a wide log pane in a 4K window ran past the old cap.
export const MAX_OSC52_BYTES = 1_000_000;

export function handleOsc52(payload: string, setClipboard: (text: string) => void): boolean {
  const [, data = ""] = payload.split(";", 2);
  if (data === "?") {
    return false; // reads are never answered
  }
  const text = atob(data);
  if (text.length > MAX_OSC52_BYTES) {
    return false; // oversized writes are dropped whole, never truncated
  }
  setClipboard(text);
  return true;
}
